from __future__ import annotations
import json, os, subprocess, sys
from pathlib import Path

def render(results):
    template=Path('README.template.md').read_text(encoding='utf-8'); c=results['config']; a=results['analysis']; v=results['validation']; d=results['design'];
    try: login=subprocess.check_output(['gh','api','user','--jq','.login'],text=True,stderr=subprocess.DEVNULL).strip()
    except Exception:
        try: login=subprocess.check_output(['git','config','user.name'],text=True).strip().lower().replace(' ','')
        except Exception: login=''
    try: tree=subprocess.check_output(['git','ls-files'],text=True).strip()
    except Exception: tree='(run git ls-files after initializing repository)'
    if not tree: tree='(files are not yet tracked; run git ls-files after initializing repository)'
    values={'github_path':f'{login}/ab-testing-checkout-funnel' if login else 'ab-testing-checkout-funnel','control_rate_pct':f"{a['control_rate']*100:.2f}",'treatment_rate_pct':f"{a['treatment_rate']*100:.2f}",'relative_lift_pct':f"{a['relative_lift']*100:.2f}",'relative_ci_low_pct':f"{a['relative_ci_low']*100:.2f}",'relative_ci_high_pct':f"{a['relative_ci_high']*100:.2f}",'time_reduction_pct':f"{a['checkout']['median_reduction']*100:.2f}",'decision':a['decision'],'alpha':c['alpha'],'target_power':c['power'],'baseline_pct':c['baseline_conversion']*100,'mde_pct':c['relative_lift']*100,'required_n':d,'actual_n':c['n_sessions']//2,'control_n':a['control_n'],'treatment_n':a['treatment_n'],'control_conversions':a['control_conversions'],'treatment_conversions':a['treatment_conversions'],'control_wilson_low':f"{results['conversion'][0]['ci_low']*100:.2f}",'control_wilson_high':f"{results['conversion'][0]['ci_high']*100:.2f}",'treatment_wilson_low':f"{results['conversion'][1]['ci_low']*100:.2f}",'treatment_wilson_high':f"{results['conversion'][1]['ci_high']*100:.2f}",'absolute_lift_pp':f"{a['absolute_lift']*100:.2f}",'absolute_ci_low_pp':f"{a['absolute_ci_low']*100:.2f}",'absolute_ci_high_pp':f"{a['absolute_ci_high']*100:.2f}",'bootstrap_ci_low_pct':f"{a['bootstrap_ci_low']*100:.2f}",'bootstrap_ci_high_pct':f"{a['bootstrap_ci_high']*100:.2f}",'p_value':f"{a['z_p_value']:.4g}",'chi_square_p':f"{a['chi_square_p_value']:.4g}",'fisher_p':f"{a['fisher_p_value']:.4g}",'adjusted_or':f"{a['adjusted_odds_ratio']:.3f}",'adjusted_or_low':f"{a['adjusted_or_ci_low']:.3f}",'adjusted_or_high':f"{a['adjusted_or_ci_high']:.3f}",'control_median':f"{a['checkout']['control_median']:.1f}",'treatment_median':f"{a['checkout']['treatment_median']:.1f}",'mean_reduction_pct':f"{a['checkout']['mean_reduction']*100:.2f}",'mann_whitney_p':f"{a['checkout']['mann_whitney_p']:.4g}",'welch_log_p':f"{a['checkout']['welch_log_p']:.4g}",'bayes_probability':f"{a['bayes_probability_treatment_better']*100:.2f}",'bayes_lift_pct':f"{a['bayes_relative_lift_mean']*100:.2f}",'bayes_ci_low_pct':f"{a['bayes_ci_low']*100:.2f}",'bayes_ci_high_pct':f"{a['bayes_ci_high']*100:.2f}",'srm_p':f"{v['srm_p_value']:.4g}",'srm_flag':str(v['srm_flag']),'aa_rate_pct':f"{v['aa_false_positive_rate']*100:.2f}",'aa_ci_low_pct':f"{v['aa_ci_low']*100:.2f}",'aa_ci_high_pct':f"{v['aa_ci_high']*100:.2f}",'empirical_power_pct':f"{v['empirical_power']*100:.2f}",'decision_reason':str(a['decision_reasons']),'python_version':sys.version.split()[0],'seed':c['seed'],'runtime_seconds':f"{results.get('runtime_seconds',0):.2f}",'file_tree':tree}
    for k,val in values.items(): template=template.replace('{{'+k+'}}',str(val))
    if '{{' in template or '}}' in template or any(w in template for w in ['TODO','TBD','populated after']): raise ValueError('README contains unresolved template language')
    Path('README.md').write_text(template,encoding='utf-8')
